var g=UnityEngine.Object.FindAnyObjectByType<Afterecho.RunnerGame>();var touch=UnityEngine.InputSystem.Touchscreen.current;bool added=touch==null;if(added)touch=UnityEngine.InputSystem.InputSystem.AddDevice<UnityEngine.InputSystem.Touchscreen>();var mouse=UnityEngine.InputSystem.Mouse.current;
