}catch(System.Exception e){UnityEditor.EditorApplication.update-=tick;release();if(added)UnityEngine.InputSystem.InputSystem.RemoveDevice(touch);g.Menu();g.invincible=false;g.volume=volume;rows.Add("FAIL "+e.Message);System.IO.File.WriteAllLines("PlaytestExports/Runner/live-contact-checks.txt",rows);UnityEngine.Debug.LogError(e);}};UnityEditor.EditorApplication.update+=tick;return "contact checks queued";
